local function createBundledUI()
	local modules = {}
	-- src/theme/tokens.lua
	modules["theme/tokens"] = (function()
-- Design tokens: the type scale, motion scale, corner radii and spacing steps
-- that every control and window part draws from. Keeping them in one module
-- means the whole interface can be retuned here instead of at several hundred
-- scattered literals.
return function(ctx)
	-- Runs before core/services, so there is no Library table yet: the tokens go
	-- onto ctx and services copies them onto Library once it exists.

	-- Type scale, named by role rather than by size. Caption and Body sit 1px apart on
	-- purpose: they are the two workhorse sizes and the difference is meant to be barely
	-- visible, not to read as a rank. Every other step is at least 2px apart. Glyph sizes
	-- for icon-font characters (close crosses, chevrons, stepper signs) are not part of
	-- this scale and stay as literals next to their container.
	local Type = {
		Caption = 12,
		Body = 13,
		Title = 15,
		Heading = 17,
		Display = 20,
		PageTitle = 22,
		Hero = 26,
	}

	-- Motion scale. Every tween picks one of these durations. The steps are far
	-- enough apart to be distinguishable; anything closer reads as the same
	-- speed and only adds noise.
	local Motion = {
		Instant = 0, -- state flips with no transition
		Fast = 0.12, -- hover, press, knob travel
		Quick = 0.15, -- small state changes: chips, checkmarks, chevrons
		Base = 0.2, -- default for colour and transparency
		Calm = 0.25, -- rows, panels, expanding sections
		Slow = 0.3, -- dialogs, sheets, page swaps
		Enter = 0.45, -- pop-in and open animations
		Linger = 0.6, -- long fades, ambient loops
	}

	-- Corner radii, by the size of the thing being rounded rather than by the
	-- number: a chip and a card should not both be 6 because they happen to be.
	local Radius = {
		Hairline = 2, -- dividers, progress tracks
		Tiny = 4, -- badges, swatches
		Small = 6, -- chips, inputs, small buttons
		Medium = 8, -- cards, dropdowns, rows
		Large = 10, -- groupboxes, panels
		Pill = 12, -- fully rounded ends
	}

	-- Spacing steps for padding and gaps, derived from the values the controls actually
	-- use rather than picked in advance. 14 is by far the most common padding in the
	-- library (29 of 114 arguments), so it is a step; the first version of this scale
	-- stopped at 16 and missed it. The ladder is 2px from Hairline to Section, then jumps
	-- to Wide. Roomy fills the hole 10 to 14 used to leave, which is why 12 is a step and
	-- 7, 9 and 11 are not: those would break the even ladder rather than complete it.
	--
	-- These steps cover 103 of the 114 padding arguments in src/ (90%). The other 11 stay
	-- as literals until the surrounding code is touched: 11 (3), 7 (4), 9 (1), and the
	-- three 12s that are paired with an 11.
	--
	-- addPadding applies the density scale itself, so every padding is density-aware
	-- whether or not the call site names a step.
	local Space = {
		None = 0, -- flush
		Hairline = 2,
		Tight = 4,
		Snug = 6,
		Base = 8,
		Cozy = 10,
		Roomy = 12,
		Loose = 14,
		Section = 16,
		Wide = 24,
	}

	local Tokens = { Type = Type, Motion = Motion, Radius = Radius, Space = Space }
	ctx.Tokens = Tokens
	ctx.Type = Type
	ctx.Motion = Motion
	ctx.Radius = Radius
	ctx.Space = Space
end
	end)()
	-- src/core/services.lua
	modules["core/services"] = (function()
-- Roblox services, executor detection, game/place info and small
-- formatting / clipboard / server-list helpers shared by the window modules.
-- Generated from work/library-minified.lua by work/refactor/split.mjs; see src/README.md.
return function(ctx)
	local TweenService = game:GetService("TweenService")
	local UserInputService = game:GetService("UserInputService")
	local GuiService = game:GetService("GuiService")
	local RunService = game:GetService("RunService")
	local HttpService = game:GetService("HttpService")
	local Players = game:GetService("Players")
	local TeleportService = game:GetService("TeleportService")
	local MarketplaceService = game:GetService("MarketplaceService")
	local Stats = game:GetService("Stats")
	local LocalPlayer = Players.LocalPlayer
	local Library = {}
	Library.Flags = {}
	Library.Windows = {}
	Library.Tokens = ctx.Tokens
	Library.Type = ctx.Type
	Library.Motion = ctx.Motion
	Library.Radius = ctx.Radius
	Library.Space = ctx.Space
	local function getExecutorName()
		local aV
		pcall(function()
			if typeof(identifyexecutor) == "function" then
				aV = (identifyexecutor())
			elseif typeof(getexecutorname) == "function" then
				aV = getexecutorname()
			end
		end)
		if type(aV) == "string" and #aV > 0 then
			return aV
		end
		return RunService:IsStudio() and "Studio" or "Unknown"
	end
	local function checkExecutorSupport(aW)
		local aX = getExecutorName()
		local aY = aW.SupportedExecutors
		if type(aY) == "table" then
			local aZ = string.lower(aX)
			for _, a0 in ipairs(aY) do
				if string.find(aZ, string.lower(tostring(a0)), 1, true) then
					return aX, true, "Your executor is supported and fully compatible."
				end
			end
			return aX, false, "Not on the supported list. Some features may not work."
		end
		local aZ = {
			{ "writefile", writefile },
			{ "readfile", readfile },
			{ "getcustomasset", getcustomasset },
			{ "setclipboard", setclipboard or toclipboard },
			{ "request", request or http_request or (syn and syn.request) },
		}
		local a_ = {}
		for _, a1 in ipairs(aZ) do
			if type(a1[2]) ~= "function" then
				table.insert(a_, a1[1])
			end
		end
		if #a_ == 0 then
			return aX, true, "Your executor is supported and fully compatible."
		end
		return aX, false, "Missing " .. table.concat(a_, ", ") .. ". Some features may not work."
	end
	local productInfoCache = nil
	local function getProductInfo()
		if productInfoCache == nil then
			local ok, a_ = pcall(function()
				return MarketplaceService:GetProductInfo(game.PlaceId)
			end)
			productInfoCache = ok and type(a_) == "table" and a_ or false
		end
		return productInfoCache or nil
	end
	local function getGameName()
		local a_ = getProductInfo()
		if a_ and a_.Name then
			return a_.Name
		end
		return RunService:IsStudio() and "Studio" or "Unknown game"
	end
	local function fetchRegion(a1)
		task.spawn(function()
			a1("Unavailable")
		end)
	end
	local NotifyColors = setmetatable({}, {
		__index = function(a1, a2)
			if a2 == "Success" or a2 == "Warning" or a2 == "Error" then
				return ctx.Theme[a2]
			end
			return nil
		end,
	})
	local function formatDuration(bB)
		bB = math.max(math.floor(bB), 0)
		local bC = math.floor(bB / 86400)
		local bD = math.floor(bB / 3600) % 24
		local bE = math.floor(bB / 60) % 60
		if bC > 0 then
			return string.format("%dd %dh", bC, bD)
		elseif bD > 0 then
			return string.format("%dh %dm", bD, bE)
		elseif bE > 0 then
			return string.format("%dm %ds", bE, bB % 60)
		end
		return string.format("%ds", bB)
	end
	local function shortenJobId(bC)
		if type(bC) ~= "string" or bC == "" then
			return "Studio"
		end
		if #bC > 16 then
			return bC:sub(1, 8) .. "..." .. bC:sub(-4)
		end
