			return HttpService:JSONDecode(bH)
		end)
		if not ok or type(bJ) ~= "table" or type(bJ.data) ~= "table" then
			return nil
		end
		return bJ.data
	end

	ctx.Library = Library
	ctx.Services.TweenService = TweenService
	ctx.Services.UserInputService = UserInputService
	ctx.Services.GuiService = GuiService
	ctx.Services.RunService = RunService
	ctx.Services.HttpService = HttpService
	ctx.Services.Players = Players
	ctx.Services.TeleportService = TeleportService
	ctx.Services.Stats = Stats
	ctx.Services.LocalPlayer = LocalPlayer
