		getGameName = getGameName,
		fetchRegion = fetchRegion,
		NotifyColors = NotifyColors,
		formatDuration = formatDuration,
		shortenJobId = shortenJobId,
		copyToClipboard = copyToClipboard,
		fetchServerList = fetchServerList,
	}
end
