	modules["theme/engine"] = (function()
-- Automatic re-theming: tracks Color3 properties that came from the theme and
-- re-applies them on SetTheme; colour parsing, rich-text Colorize and theme switching APIs.
-- Generated from work/library-minified.lua by work/refactor/split.mjs; see src/README.md.
return function(ctx)
	local Motion = ctx.Motion
	local Library = ctx.Library
	local themeColorKeys = ctx.Presets.themeColorKeys
	local RunService = ctx.Services.RunService

	local tweenInfoCache = {}
	local themeBindings = {}
	local themeWatchers = {}
	local colorToThemeKey = {}
	local staleMarks = {}
	local themeBindingCount = 0
	local themeSweepThreshold = 4000
	local function sweepDetached(Y, Z)
		for _ in pairs(Y) do
			if _.Parent == nil then
				if staleMarks[_] then
					Y[_] = nil
					staleMarks[_] = nil
					if Z then
						themeBindingCount -= 1
					end
				else
					staleMarks[_] = true
				end
			else
				staleMarks[_] = nil
			end
		end
	end
	local function sweepThemeTables()
		sweepDetached(themeBindings, true)
		sweepDetached(themeWatchers, false)
		themeSweepThreshold = math.max(4000, themeBindingCount * 2)
	end
	local function colorKey(_)
		return math.floor(_.R * 255 + 0.5) .. "," .. math.floor(_.G * 255 + 0.5) .. "," .. math.floor(_.B * 255 + 0.5)
	end
	local function rebuildColorIndex()
		table.clear(colorToThemeKey)
		for aa = #themeColorKeys, 1, -1 do
			local ab = themeColorKeys[aa]
			colorToThemeKey[colorKey(Library.Theme[ab])] = ab
		end
	end
	rebuildColorIndex()
	local function trackThemeColors(ab, ac)
		for ad, ae in pairs(ac) do
			if typeof(ae) == "Color3" then
				local af = colorToThemeKey[colorKey(ae)]
				local ag = themeBindings[ab]
				if af then
					if not ag then
						ag = {}
						themeBindings[ab] = ag
						themeBindingCount += 1
						if themeBindingCount >= themeSweepThreshold then
							sweepThemeTables()
						end
					end
					ag[ad] = af
				elseif ag then
					ag[ad] = nil
				end
			end
		end
	end
	local displayedTheme = table.clone(Library.Theme)
	local themeTransition = nil
	local function applyBinding(ae, af, ag)
		for ah, ai in pairs(af) do
			local aj = ag[ai]
			if aj then
				ae[ah] = aj
			end
		end
	end
	local function applyThemeColors(af)
		for ag, ah in pairs(themeBindings) do
			pcall(applyBinding, ag, ah, af)
		end
	end
	local function animateThemeChange(ag)
		if themeTransition then
			themeTransition:Disconnect()
			themeTransition = nil
		end
		local ah, ai = {}, {}
		for _, ak in ipairs(themeColorKeys) do
			local al = Library.Theme[ak]
			local am = displayedTheme[ak] or al
			if am ~= al then
				ah[ak] = am
				ai[ak] = am
			end
		end
		local function aj()
			for _, al in ipairs(themeColorKeys) do
				ai[al] = Library.Theme[al]
				displayedTheme[al] = Library.Theme[al]
			end
