	function Window:Rejoin()
		self:Notify({ Title = "Rejoining", Content = "Teleporting back into this server", Icon = "refresh-cw", Duration = 3 })
		task.spawn(function()
			local ok, bZ = pcall(function()
				if #Players:GetPlayers() <= 1 or game.JobId == "" then
					TeleportService:Teleport(game.PlaceId, LocalPlayer)
				else
					TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, LocalPlayer)
				end
			end)
			if not ok then
				self:Notify({ Title = "Rejoin failed", Content = tostring(bZ), Type = "Error", Duration = 4 })
			end
		end)
	end
	local function hopServer(bZ, b_, b0, b1)
