				return
			end
			local b3 = {}
			for _, b5 in ipairs(b2) do
				if type(b5) == "table" and b5.id ~= game.JobId then
					local b6, b7 = tonumber(b5.playing), tonumber(b5.maxPlayers)
					if b6 and b7 and b6 < b7 then
