		tween(ci, { BackgroundTransparency = 0 }, Motion.Fast, Enum.EasingStyle.Quad)
		tween(cj, { Transparency = 0 }, Motion.Fast, Enum.EasingStyle.Quad)
		tween(self.Scale, { Scale = (self._fitScale or 1) * 0.985 }, Motion.Fast, Enum.EasingStyle.Quad)
