				tween(self._miniScale, { Scale = 1 }, Motion.Slow, Enum.EasingStyle.Quint)
				tween(cd, { GroupTransparency = 0 }, Motion.Quick, Enum.EasingStyle.Quad)
				fadeGhost(self, ci, cj, Motion.Base)
				if self.IslandStyle == "Always Show" then
					task.delay(0.22, function()
