	modules["core/trusted"] = (function()
-- Thread-identity aware wrapper: when the window GUI is protected, public methods are
-- re-dispatched through Heartbeat. Runs last, after every method exists.
-- Generated from work/library-minified.lua by work/refactor/split.mjs; see src/README.md.
return function(ctx)
