	local Library = ctx.Library
	local RunService = ctx.Services.RunService
	local Window = ctx.Window

	local getIdentity = getthreadidentity or getidentity or get_thread_identity or (syn and syn.get_thread_identity)
	local setIdentity = setthreadidentity or setidentity or set_thread_identity or (syn and syn.set_thread_identity)
	local savedIdentity = nil
	if getIdentity then
		local ok, cg = pcall(getIdentity)
		if ok and type(cg) == "number" then
			savedIdentity = cg
		end
	end
	local function guiIsProtected()
		local cg = Library.Windows[#Library.Windows]
		local ch = cg and cg.Gui
		if typeof(ch) ~= "Instance" then
			return false
		end
		return not pcall(function()
			return ch.Name
		end)
	end
	local trustedQueue = {}
	RunService.Heartbeat:Connect(function()
		if #trustedQueue == 0 then
			return
		end
		local ch = trustedQueue
		trustedQueue = {}
		for _, cj in ipairs(ch) do
			cj()
		end
	end)
	local function callTrusted(ci, ...)
		local cj = table.pack(...)
		local ck = nil
		local cl = false
		table.insert(trustedQueue, function()
			if not cl then
				ck = table.pack(pcall(ci, table.unpack(cj, 1, cj.n)))
			end
		end)
		local cm = os.clock() + 5
		while ck == nil do
			if os.clock() > cm then
				cl = true
				error("[OuroFlow] trusted call timed out", 0)
			end
			task.wait()
		end
		if not ck[1] then
			error(ck[2], 0)
		end
