				if setIdentity then
					pcall(setIdentity, savedIdentity or 8)
				end
				if guiIsProtected() then
					return wrapResults(callTrusted(cl, ...))
				end
			end
			return wrapResults(cl(...))
		end
	end
	function wrapResults(...)
		for cl = 1, select("#", ...) do
			local cm = select(cl, ...)
			if type(cm) == "table" and not wrappedTables[cm] then
				local cn = getmetatable(cm)
				if cn ~= Window and cn ~= Container then
					wrappedTables[cm] = true
					for co, cp in pairs(cm) do
						if type(co) == "string" and type(cp) == "function" and co:sub(1, 1) ~= "_" then
							cm[co] = wrapMethod(cp)
						elseif type(co) == "number" and type(cp) == "table" then
							wrapResults(cp)
						end
					end
				end
			end
		end
		return ...
	end
	for _, cm in ipairs({ Library, Window, Container }) do
		for cn, co in pairs(cm) do
			if type(cn) == "string" and type(co) == "function" and cn:sub(1, 1) ~= "_" then
